theorem kSeparated_reflectFinset {n d k : ℕ} {s : Finset (Cube n d)}
    (hs : KSeparated (s : Set (Cube n d)) k) :
    KSeparated (reflectFinset s : Set (Cube n d)) k

private theorem mem_fullChainFinset_iff (k d : ℕ) (x : Cube k d) :
    x ∈ fullChainFinset k d ↔
      ((LargeK.cubeSCD k d).encode x).1 = fullChainIndex k d

private theorem comparable_of_mem_fullChainFinset (k d : ℕ)
    {x y : Cube k d} (hx : x ∈ fullChainFinset k d)
    (hy : y ∈ fullChainFinset k d) : x ≤ y ∨ y ≤ x

private theorem card_blockFiber_eq_tailSlice {k n d : ℕ}
    (P : Finset (Cube k d × Cube n d)) (b : Cube k d) :
    (blockFiber P b).card = (tailSlice P b).card

private theorem density_add_le (n d k : ℕ) :
    density (k + n) d k ≤
      1 / ((d + 1 : ℝ) ^ k) + contraction d k * density n d k

private theorem density_subsequence_le (r t d k : ℕ) :
    density (r + t * k) d k ≤
      1 / (d * k + 1 : ℝ) + (contraction d k) ^ t

private theorem lower_reachable_lower {n r : ℕ}
    (s t : Finset (Fin n)) (hs : s.card = r) (ht : t.card = r) :
    (adjacentLayerGraph n r).Reachable (lowerVertex s hs) (lowerVertex t ht)

private theorem reachable_lowerVertex {n r : ℕ} (x : AdjacentLayerVertex n r) :
    ∃ (s : Finset (Fin n)) (hs : s.card = r),
      (adjacentLayerGraph n r).Reachable x (lowerVertex s hs)

private theorem binomialDifference_eq_choose_sub_previous (n a : ℕ) :
    DOne.binomialDifference n a =
      (n.choose a : ℤ) - (previousLayerCard n a : ℤ)

private theorem card_le_one_of_le_one {n : ℕ} (hn : n ≤ 1)
    (A : Finset (Cube n 1)) (hA : Antichain (A : Set (Cube n 1))) :
    A.card ≤ 1

private theorem eq_singleton_of_card_eq_one_of_mem {α : Type*} [DecidableEq α]
    {A : Finset α} {x : α}
    (hcard : A.card = 1) (hx : x ∈ A) : A = {x}

private theorem eq_middleLayer_of_le_one_of_card_eq_one {n : ℕ} (hn : n ≤ 1)
    (A : Finset (Cube n 1)) (hcard : A.card = 1) :
    A = lowerMiddleLayer n ∨ A = upperMiddleLayer n

private theorem hookNumberLE_eq_left {a b : ℕ} (hab : a ≤ b)
    (p : Fin (a + 1) × Fin (b + 1)) (h : (p.1 : ℕ) + p.2 ≤ b) :
    (hookNumberLE hab p : ℕ) = p.1

private theorem hookNumberLE_eq_right {a b : ℕ} (hab : a ≤ b)
    (p : Fin (a + 1) × Fin (b + 1)) (h : ¬((p.1 : ℕ) + p.2 ≤ b)) :
    (hookNumberLE hab p : ℕ) = b - p.2

private theorem hookNumberLE_le_rank {a b : ℕ} (hab : a ≤ b)
    (p : Fin (a + 1) × Fin (b + 1)) :
    (hookNumberLE hab p : ℕ) ≤ (p.1 : ℕ) + p.2

private theorem hookNumberLE_add_position {a b : ℕ} (hab : a ≤ b)
    (p : Fin (a + 1) × Fin (b + 1)) :
    (hookNumberLE hab p : ℕ) + hookPositionLE hab p = (p.1 : ℕ) + p.2

private theorem card_gridHookTarget {a b : ℕ} (hab : a ≤ b) :
    Fintype.card (Σ r : Fin (a + 1), Fin (a + b - 2 * (r : ℕ) + 1)) =
      Fintype.card (Fin (a + 1) × Fin (b + 1))

private theorem gridHookEquivLE_mono {a b : ℕ} (hab : a ≤ b)
    {p q : Fin (a + 1) × Fin (b + 1)}
    (hchain : (gridHookEquivLE hab p).1 = (gridHookEquivLE hab q).1)
    (hpos : ((gridHookEquivLE hab p).2 : ℕ) ≤ (gridHookEquivLE hab q).2) :
    p ≤ q

private theorem cuboidSuccEquiv_order {n : ℕ} (bounds : Fin (n + 1) → ℕ)
    {x y : Cuboid bounds} (hxy : cuboidSuccEquiv bounds x ≤ cuboidSuccEquiv bounds y) :
    x ≤ y

private theorem productSCD_index_card_eq_blockSum
    {P Q : Type*} [LE P] [LE Q] {rankP : P → ℕ} {rankQ : Q → ℕ}
    {NP NQ : ℕ} (S : RankedSCD P rankP NP) (T : RankedSCD Q rankQ NQ) :
    @Fintype.card (productSCD S T).Index (productSCD S T).indexFintype =
      (indexPairFinset S T).sum
        (fun ij ↦ min (S.steps ij.1) (T.steps ij.2) + 1)

theorem RankedSCD.comparable_of_same_chain
    {P : Type*} [LE P] {rankP : P → ℕ} {N : ℕ}
    (S : RankedSCD P rankP N) {x y : P}
    (hchain : (S.encode x).1 = (S.encode y).1) : x ≤ y ∨ y ≤ x

private theorem splitCuboidEquiv_le_iff {p q : ℕ}
    (bounds : Fin (p + q) → ℕ) (x y : Cuboid bounds) :
    splitCuboidEquiv bounds x ≤ splitCuboidEquiv bounds y ↔ x ≤ y

private theorem cuboid_hammingDistance_le_right_of_left_eq {p q : ℕ}
    (bounds : Fin (p + q) → ℕ) {x y : Cuboid bounds}
    (hleft : (splitCuboidEquiv bounds x).1 = (splitCuboidEquiv bounds y).1) :
    Cuboid.hammingDistance x y ≤ q

private theorem cuboid_hammingDistance_le_left_of_right_eq {p q : ℕ}
    (bounds : Fin (p + q) → ℕ) {x y : Cuboid bounds}
    (hright : (splitCuboidEquiv bounds x).2 = (splitCuboidEquiv bounds y).2) :
    Cuboid.hammingDistance x y ≤ p

theorem lowerStartingWeight_eq_auxiliaryWeightNat {n k a : ℕ}
    (houter : 2 * a ≤ n - k) :
    lowerStartingWeight n k a = auxiliaryWeightNat n k a

theorem lowerStartingWeight_eq_innerWeight {n k a : ℕ}
    (hinner : n - k < 2 * a) :
    lowerStartingWeight n k a = innerWeight n k a

@[simp]
theorem singletonChain_vertices (x : Cube n 1) :
    (singletonChain x).toChain.vertices = {x}

theorem vertices_eq_pair_of_steps_eq_one (C : BooleanChain n)
    (hsteps : (C.steps : ℕ) = 1) :
    C.toChain.vertices = {C.toChain.first, C.toChain.last}

theorem exists_cubePermEquiv_eq_of_rank_eq {x y : Cube n 1}
    (hxy : Cube.rank x = Cube.rank y) :
    ∃ e : Equiv.Perm (Fin n), cubePermEquiv e x = y

theorem chainWeight_of_mem_startGroup {k a : ℕ} {C : BooleanChain n}
    (hC : C ∈ startGroup n k a) :
    chainWeight n k C = startGroupChainWeight n k a

theorem sum_chainWeight_startGroup {k a : ℕ}
    (ha : (startGroup n k a).Nonempty) :
    ∑ C ∈ startGroup n k a, chainWeight n k C = (startingWeight n k a : ℝ)

theorem typeCounts_eq_of_zeroCount_eq_twoCount_eq {x y : Cube n 2}
    (hzero : zeroCount x = zeroCount y) (htwo : twoCount x = twoCount y) :
    TypeCounts.ofVertex x = TypeCounts.ofVertex y

theorem typeOf_eq_of_zeroCount_eq_twoCount_eq {n : ℕ} {x y : Cube n 2}
    (hzero : zeroCount x = zeroCount y) (htwo : twoCount x = twoCount y) :
    ∀ j : Fin 3, Cube.typeOf x j = Cube.typeOf y j

theorem exists_coordinatePermutation_of_same_type {n : ℕ} {x y : Cube n 2}
    (hzero : zeroCount x = zeroCount y) (htwo : twoCount x = twoCount y) :
    ∃ e : Equiv.Perm (Fin n), ∀ i, y (e i) = x i

private theorem auxiliaryWeight_initial_closedForm (n a c : ℕ)
    (hc : 0 < c) (hca : c ≤ a) (hac : a + c ≤ n) :
    auxiliaryWeight n n a c = initialWeightClosedForm n a c

private theorem initialWeightClosedForm_pos (n a c : ℕ)
    (hc : 0 < c) (hca : c ≤ a) (hac : a + c ≤ n) :
    0 < initialWeightClosedForm n a c

