    (hk : 0 < k) (hkn : k ≤ n) (hc : 0 ≤ c) (hca : c ≤ a)
    (hac : a + c ≤ n + 1) : AuxiliaryWeightPascal n k a c

private theorem hammingDistance_evenVertex_succ (B : BasicChain n) (i : ℕ)
    (hi : i < B.width) :
    Cube.hammingDistance (B.evenVertex i) (B.evenVertex (i + 1)) = 1

private theorem evenVertex_succ_eq_of_ne (B : BasicChain n) (i : ℕ)
    (hi : i < B.width) (q : Fin n) (hq : q ≠ B.coordinate ⟨i, hi⟩) :
    B.evenVertex i q = B.evenVertex (i + 1) q

private theorem recursionCoordinate_lt {n : ℕ} {a c : ℤ}
    (hvalid : 0 ≤ a ∧ 0 ≤ c ∧ a + c ≤ n)
    (hnotBase : ¬(a = n ∧ c = 0)) : a < n

private theorem recursionMeasure_decreases {n : ℕ} {a r : ℤ}
    (ha : 0 ≤ a) (han : a < n) (hr : 0 < r) :
    n - (a + r).toNat < n - a.toNat

